insert into public.chat_rules select * from json_populate_recordset(null::public.chat_rules, '[{"lang":"en","title":"⚠️ Community rules","rules":["🤝 Respect all members","🚫 No insults or harassment","📵 No racism or discrimination","🔗 No suspicious links or ads","🔒 Do not share personal information","🛑 No inappropriate content","🏛️ No politics","⚠️ Violations may lead to a mute or a ban"],"accept_text":"I agree and enter the chat","decline_text":"Decline and go home","updated_at":"2026-10-04T19:32:33.175051+00:00"},{"lang":"ar","title":"⚠️ قواعد المجتمع","rules":["🤝 احترام جميع الأعضاء","🚫 لا إهانات أو مضايقات","📵 لا عنصرية أو تمييز","🔗 لا روابط أو إعلانات مشبوهة","🔒 لا تشارك معلوماتك الشخصية","🛑 لا محتوى غير لائق","🏛️ لا سياسة","⚠️ قد تؤدي الانتهاكات إلى كتم الصوت أو الحظر"],"accept_text":"أوافق وأدخل الدردشة","decline_text":"الرفض والعودة إلى المنزل","updated_at":"2026-10-04T19:32:33.175051+00:00"},{"lang":"tr","title":"⚠️ Topluluk kuralları","rules":["🤝 Herkese saygı göster","🚫 Hakaret ve taciz yok","📵 Irkçılık ve ayrımcılık yok","🔗 Şüpheli bağlantı ve izinsiz reklam yok","🔒 Kişisel bilgi paylaşma","🛑 Uygunsuz içerik yok","🏛️ Siyasi tartışma yok","⚠️ İhlaller susturma veya yasaklanmayla sonuçlanabilir"],"accept_text":"Kabul ediyorum ve Sohbete giriyorum","decline_text":"Reddet ve Ana Sayfaya dön","updated_at":"2026-10-04T19:32:33.175051+00:00"},{"lang":"pt","title":"⚠️ Regras da comunidade","rules":["🤝 Respeite todos os membros","🚫 Sem insultos ou assédio","📵 Sem racismo ou discriminação","🔗 Sem links suspeitos ou anúncios","🔒 Não compartilhe informações pessoais","🛑 Sem conteúdo inadequado","🏛️ Sem política","⚠️ Violações podem levar a silenciamento ou banimento"],"accept_text":"Concordo e entrar no chat","decline_text":"Recusar e voltar ao início","updated_at":"2026-10-04T19:32:33.175051+00:00"},{"lang":"es","title":"⚠️ Reglas de la comunidad","rules":["🤝 Respeta a todos los miembros","🚫 Sin insultos ni acoso","📵 Sin racismo ni discriminación","🔗 Sin enlaces sospechosos ni anuncios","🔒 No compartas información personal","🛑 Sin contenido inapropiado","🏛️ Sin política","⚠️ Las infracciones pueden provocar silencio o expulsión"],"accept_text":"Acepto y entro al chat","decline_text":"Rechazar y volver al inicio","updated_at":"2026-10-04T19:32:33.175051+00:00"},{"lang":"ru","title":"⚠️ Правила сообщества","rules":["🤝 Уважайте всех участников","🚫 Без оскорблений и травли","📵 Без расизма и дискриминации","🔗 Без подозрительных ссылок и рекламы","🔒 Не делитесь личными данными","🛑 Без неприемлемого контента","🏛️ Без политики","⚠️ Нарушения могут привести к мьюту или бану"],"accept_text":"Я согласен и вхожу в чат","decline_text":"Отказаться и вернуться домой","updated_at":"2026-10-04T19:32:33.175051+00:00"},{"lang":"zh","title":"⚠️ 社区规则","rules":["🤝 尊重所有成员","🚫 禁止侮辱和骚扰","📵 禁止种族主义和歧视","🔗 禁止可疑链接和广告","🔒 不要分享个人信息","🛑 禁止不当内容","🏛️ 禁止政治话题","⚠️ 违规可能导致禁言或封禁"],"accept_text":"我同意并进入聊天","decline_text":"拒绝并返回首页","updated_at":"2026-10-04T19:32:33.175051+00:00"},{"lang":"fr","title":"⚠️ Règles de la communauté","rules":["🤝 Respectez tous les membres","🚫 Pas d''insultes ni de harcèlement","📵 Pas de racisme ni de discrimination","🔗 Pas de liens suspects ni de publicités","🔒 Ne partagez pas d''informations personnelles","🛑 Pas de contenu inapproprié","🏛️ Pas de politique","⚠️ Les infractions peuvent entraîner un silence ou un bannissement"],"accept_text":"J''accepte et j''entre dans le chat","decline_text":"Refuser et revenir à l''accueil","updated_at":"2026-10-04T19:32:33.175051+00:00"}]'::json) on conflict do nothing;
